/* Fills ten 0x90-byte entries from the float tables, then runs the id list at a[0x21] against them. */
void draw_electric_gate_beams(char *a) {
    Quad arr[2][5];
    char tmp[0x40];
    int tex, i, j, k, n, nx, nj, r1, r2, off;
    float ang, t;
    unsigned short *p;
    unsigned short *nxt;
    short cur;

    ang = IntToFloat(rilgar_frame_count & 0x3F) / 63.0f * 6.28318f;
    i = 0;
    do {
        nx = i + 1;
        t = (FastSin(ang) + 1.0f) * 0.5f;
        r1 = FastTweenColor(*(int *)&electric_gate_outer_color_from, *(int *)&electric_gate_outer_color_to, t);
        r2 = FastTweenColor(*(int *)&electric_gate_inner_color_from, *(int *)&electric_gate_inner_color_to, t);
        ang = FastAddRots(ang, 1.2566371f);
        j = 0;
        do {
            tex = GetEffectTex(*(int *)&electric_gate_effect_tex);
            nj = j + 1;
            arr[j][i].a88 = (s64)*(int *)&electric_gate_alpha_a | ((s64)*(int *)&electric_gate_alpha_b << 2) | ((s64)*(int *)&electric_gate_alpha_c << 4) | ((s64)*(int *)&electric_gate_alpha_d << 6) | 0x8000000000LL;
            arr[j][i].a78 = tex;
            arr[j][i].a80 = 0xFF9000000260LL;
            arr[j][i].a70 = 0;
            for (n = 0; n < 4; n++) {
                arr[j][i].uv[n][0] = ((float (*)[2])electric_gate_quad_uvs)[n][0];
                arr[j][i].uv[n][1] = ((float (*)[2])electric_gate_quad_uvs)[n][1];
                if (j != 0) {
                    arr[j][i].c[n] = r1;
                    {
                        qw128 *src = &((qw128 *)electric_gate_outer_corners)[n];
                        qcopy(&arr[j][i].v[n], src);
                    }
                    ((float *)&arr[j][i].v[n])[2] += (float)(i + 1);
                } else {
                    arr[0][i].c[n] = r2;
                    {
                        qw128 *src = &((qw128 *)electric_gate_inner_corners)[n];
                        qcopy(&arr[0][i].v[n], src);
                    }
                    ((float *)&arr[0][i].v[n])[2] += (float)(i + 1);
                }
            }
            j = nj;
        } while (j < 2);
        i = nx;
    } while (i < 5);

    p = (unsigned short *)rilgar_moby_groups[*(unsigned char *)(a + 0x21)];
    do {
        char *base;
        off = (*p & 0x7FFF) << 8;
        base = (char *)(off + (int)moby_pool_4f60_r);
        nxt = p + 1;
        if (*(short *)(base + 0xA6) == 0x346 && *(unsigned char *)(base + 0x20) == 1) {
            copy_matrix_rotation(tmp, base + 0xC0);
            qcopy(tmp + 0x30, (char *)(off + (int)moby_pool_4f60_r) + 0x10);
            *(float *)(tmp + 0x3C) = 1.0f;
            for (k = 0; k < 5; k++) {
                draw_world_quad(&arr[0][k], tmp, 0);
                draw_world_quad(&arr[1][k], tmp, 0);
            }
        }
        cur = *(short *)p;
        p = nxt;
    } while (cur >= 0);
}
