/* Adapted from Lombyte's project (GPL-3.0) for PAL by OpenRAC's tools/port.py: src/overlays/l05/gameplay/entities/0030d6a0.c, FUN_L05_0030f5c8. */
void pipe_mounted_grating_update(struct Moby *moby) {
    float vel[4];
    float spin_vel[4];
    float dir[4];
    float drift[4];
    float pos[4];
    struct Moby *piece;
    float angle;
    float life;
    float speed;
    int j, spin;
    if (MobyGetHitMessage(moby, 0xB30000, 0) != 0) {
        piece = CreateMoby(0x3D4);
        if (piece != 0) {
            char *vars;
            piece->spawn_frame = moby->spawn_frame;
            piece->visible = 1;
            vars = (char *)piece->pvars;
            piece->draw_dist = 0x40;
            piece->update_dist = 0x40;
            qcopy(&piece->pos, &moby->pos);
            qcopy(&piece->rot, &moby->rot);
            speed = random_float_between(5.0f, 12.0f);
            FastVecScale(vel, &moby->rot_row0, -(speed * g_frame_time));
            clear_u64_value(spin_vel);
            initialize_moby_launch_motion(piece, moby, vel, spin_vel, scale_ticks(60));
            *(int *)(vars + 0xC) = 0x200;
        }
        Moby_PlaySound(0, 0, piece);
        angle = 0.0f;
        {
            int i;
            for (i = 0; i < 6; i++) {
                angle = FastAddRots(angle, 1.0471976f);
                piece = CreateMoby(0x3D5);
                if (piece != 0) {
                    char *vars = (char *)piece->pvars;
                    *(u128_10A90 *)spin_vel = 0;
                    *(u128_10A90 *)drift = 0;
                    spin_vel[2] = 0.75f;
                    drift[1] = FastSin(angle) * 1.4f;
                    drift[2] = FastCos(angle) * 1.4f;
                    *(u128_10A90 *)dir = *(u128_10A90 *)drift;
                    matrix_mul_vec3(dir, dir, &moby->rot_row0);
                    for (j = 0; j < 10; j++) {
                        float size;
                        rand_vec(drift, g_frame_time * 1.5f, g_frame_time * 2.0f);
                        FastVecScale(pos, drift, 5.0f);
                        FastVecAdd(pos, pos, dir);
                        FastVecAdd(pos, pos, &moby->pos);
                        spin = random_integer_below(2);
                        if (spin == 0) {
                            spin--;
                        }
                        size = random_float_between(0.4f, 0.5f);
                        PartType53Spawn(pos, scale_ticks(25), size * 0.2f, size, 0x7F207F7F, 0, spin, drift,
                                         0.0f);
                        spin = -spin;
                        PartType53Spawn(pos, scale_ticks(25), size * 0.14f, size * 0.7f, 0x7F7F7F7F, 1, spin, drift,
                                         0.0f);
                    }
                        piece->spawn_frame = moby->spawn_frame;
                    piece->draw_dist = 0x40;
                    piece->visible = 1;
                    piece->update_dist = 0x40;
                        qcopy(&piece->pos, &moby->pos);
                    qcopy(&piece->rot, &moby->rot);
                    speed = random_float_between(0.0f, 24.0f);
                    life = random_float_between(60.0f, 120.0f);
                    FastVecScale(vel, &moby->rot_row0, -(speed * g_frame_time));
                    clear_u64_value(spin_vel);
                    initialize_moby_launch_motion(piece, moby, vel, spin_vel, truncate_float_to_s32(multiply_global_factor(life)));
                    *(int *)(vars + 0xC) = 0x200;
                    piece->rot.x = angle;
                    moby_build_matrix_r(piece);
                }
            }
        }
        moby->command = 1;
        record_moby_context_bytes(&moby->command, 1, moby, 1, rilgar_saved_moby_bytes);
        DeleteMoby_r(moby);
    } else if (moby->command) {
        DeleteMoby_r(moby);
    }
}
